export async function closeTestEngines(
  clientsToClose: WebSocket[],
  engines: Array<{wss: {clients: {size: number}}; stop: () => Promise<void>}>
): Promise<void> {
  for (const client of clientsToClose.splice(0)) client.terminate();
  for (const engine of engines.splice(0)) {
    await eventually(() => engine.wss.clients.size === 0);
    await engine.stop();
  }
}

export const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

